const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, BorderStyle, WidthType, ShadingType, LevelFormat,
  HeadingLevel
} = require('docx');
const fs = require('fs');

const border = { style: BorderStyle.SINGLE, size: 1, color: "CCCCCC" };
const borders = { top: border, bottom: border, left: border, right: border };
const noBorder = { style: BorderStyle.NONE, size: 0, color: "FFFFFF" };
const noBorders = { top: noBorder, bottom: noBorder, left: noBorder, right: noBorder };

function headerCell(text, shade) {
  return new TableCell({
    borders,
    width: { size: 3120, type: WidthType.DXA },
    shading: { fill: shade, type: ShadingType.CLEAR },
    margins: { top: 100, bottom: 100, left: 150, right: 150 },
    children: [new Paragraph({
      alignment: AlignmentType.CENTER,
      children: [new TextRun({ text, bold: true, size: 22, font: "Arial", color: "FFFFFF" })]
    })]
  });
}

function dataCell(text, shade, width = 3120) {
  return new TableCell({
    borders,
    width: { size: width, type: WidthType.DXA },
    shading: { fill: shade || "FFFFFF", type: ShadingType.CLEAR },
    margins: { top: 80, bottom: 80, left: 150, right: 150 },
    children: [new Paragraph({
      children: [new TextRun({ text, size: 20, font: "Arial" })]
    })]
  });
}

function sectionHeader(text, color) {
  return new TableRow({
    children: [
      new TableCell({
        borders,
        columnSpan: 3,
        width: { size: 9360, type: WidthType.DXA },
        shading: { fill: color, type: ShadingType.CLEAR },
        margins: { top: 100, bottom: 100, left: 150, right: 150 },
        children: [new Paragraph({
          children: [new TextRun({ text, bold: true, size: 22, font: "Arial", color: "FFFFFF" })]
        })]
      })
    ]
  });
}

function itemRow(item, qty, notes, shade) {
  return new TableRow({
    children: [
      dataCell(item, shade, 4200),
      dataCell(qty, shade, 1560),
      dataCell(notes, shade, 3600),
    ]
  });
}

const sections = [
  {
    label: "RICE & PANTRY",
    color: "1A6B3C",
    items: [
      ["Bomba rice (short-grain Spanish rice)", "2 cups", "Mahatma or Goya brand — rice aisle"],
      ["Saffron threads", "1 small jar", "Spice aisle — La Flor brand if available"],
      ["Chicken or seafood broth (32 oz)", "1 carton", "Swanson or store brand — soup aisle"],
      ["Sweet smoked paprika (pimentón dulce)", "1 jar", "Spice aisle"],
      ["Olive oil (extra virgin)", "1 bottle", "Oil aisle — any brand"],
      ["Dry white wine", "1 bottle", "Cooking wine aisle or liquor"],
      ["Kosher salt", "1 box", "Diamond Crystal or Morton"],
      ["Crushed red pepper flakes", "1 jar", "Spice aisle"],
    ]
  },
  {
    label: "PRODUCE",
    color: "2E7D9E",
    items: [
      ["White onion", "1 medium", "Produce section"],
      ["Red bell pepper", "1", "Produce section"],
      ["Roma tomatoes", "3", "Produce section"],
      ["Garlic (fresh bulb)", "1 bulb", "10 cloves needed — produce section"],
      ["Fresh flat-leaf parsley", "1 bunch", "Produce section"],
      ["Lemons", "1–2", "Produce section"],
    ]
  },
  {
    label: "SEAFOOD",
    color: "1B5E8A",
    items: [
      ["Large shrimp, shell-on 16/20 count", "2 lbs", "Fresh or frozen seafood section"],
    ]
  },
  {
    label: "DAIRY",
    color: "7B4F9E",
    items: [
      ["Unsalted butter", "1 stick", "Dairy aisle — Land O'Lakes or store brand"],
    ]
  },
];

const rows = [
  new TableRow({
    tableHeader: true,
    children: [
      headerCell("INGREDIENT", "0C3547"),
      headerCell("QTY", "0C3547"),
      headerCell("WALMART NOTES", "0C3547"),
    ]
  })
];

let toggle = false;
for (const section of sections) {
  rows.push(sectionHeader(section.label, section.color));
  for (const [item, qty, notes] of section.items) {
    rows.push(itemRow(item, qty, notes, toggle ? "F4F8FB" : "FFFFFF"));
    toggle = !toggle;
  }
}

const doc = new Document({
  styles: {
    default: { document: { run: { font: "Arial", size: 20 } } }
  },
  sections: [{
    properties: {
      page: {
        size: { width: 12240, height: 15840 },
        margin: { top: 1080, right: 1080, bottom: 1080, left: 1080 }
      }
    },
    children: [
      new Paragraph({
        alignment: AlignmentType.CENTER,
        spacing: { after: 80 },
        children: [new TextRun({ text: "WALMART SHOPPING LIST", bold: true, size: 36, font: "Arial", color: "0071CE" })]
      }),
      new Paragraph({
        alignment: AlignmentType.CENTER,
        spacing: { after: 60 },
        children: [new TextRun({ text: "Ironbound Gambas al Ajillo over Saffron Paella Rice", size: 24, font: "Arial", color: "333333", italics: true })]
      }),
      new Paragraph({
        alignment: AlignmentType.CENTER,
        spacing: { after: 300 },
        children: [new TextRun({ text: "Serves 4  |  Inspired by Iberia Tavern, Newark NJ", size: 20, font: "Arial", color: "777777" })]
      }),
      new Table({
        width: { size: 9360, type: WidthType.DXA },
        columnWidths: [4200, 1560, 3600],
        rows
      }),
      new Paragraph({
        spacing: { before: 300 },
        alignment: AlignmentType.CENTER,
        children: [new TextRun({ text: "TIP: Save shrimp shells to make homemade stock — simmer with onion, bay leaf, and water for 20 minutes before starting the rice.", size: 18, font: "Arial", color: "555555", italics: true })]
      }),
    ]
  }]
});

Packer.toBuffer(doc).then(buffer => {
  fs.writeFileSync("/home/claude/walmart_shopping_list.docx", buffer);
  console.log("Done.");
});

